// ELEMENTS:
// 1. Foto (src) que começa ao anoitecer e "acende as luzes": o brilho sobe e uma luz quente passa em diagonal
// 2. Aproximação lenta
// 3. Eyebrow + filete azul IAD + legenda centrada em serifa branca
// 4. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { MediaImg as Img } from "../media";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#0E1626";
const NAVY_RGB = "14,22,38";
const CYAN = "#05B8E6";
const WHITE = "#F4F1EA";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.24) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.1, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const LuzAcender: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const u = format === "landscape" ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const T = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const src = String(p.src ?? "");
  const eyebrow = String(p.eyebrow ?? "").trim();
  const caption = String(anim.text ?? "").trim();

  const show = (delay: number, len = 0.7): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing: EASE });
  const rise = (delay: number): React.CSSProperties => {
    const t = show(delay);
    return { opacity: t, transform: `translateY(${(1 - t) * 22 * u}px)` };
  };
  // The room starts at dusk and "the lights come on": brightness rises while a
  // soft diagonal glow sweeps across once.
  const lit = show(0.15, 1.4);
  const sweep = interpolate(f, [Math.round(0.2 * fps), Math.round(1.7 * fps)], [-60, 160], { ...clamp, easing: Easing.inOut(Easing.sin) });
  const zoom = interpolate(f, [0, T], [1.03, 1.1], { ...clamp, easing: Easing.inOut(Easing.sin) });
  const rule = show(0.9, 0.8);

  return (
    <AbsoluteFill style={{ textShadow: "0 2px 18px rgba(0,0,0,0.45)", overflow: "hidden", backgroundColor: NAVY }}>
      <AbsoluteFill style={{ transform: `scale(${zoom})` }}>
        {src ? (
          <Img
            src={src}
            style={{
              width: "100%",
              height: "100%",
              objectFit: "cover",
              filter: `saturate(${0.45 + 0.43 * lit}) contrast(1.05) brightness(${0.42 + 0.58 * lit})`,
            }}
          />
        ) : null}
      </AbsoluteFill>
      <AbsoluteFill
        style={{
          background: `linear-gradient(115deg, rgba(255,240,215,0) ${sweep - 30}%, rgba(255,240,215,0.22) ${sweep}%, rgba(255,240,215,0) ${sweep + 30}%)`,
          mixBlendMode: "screen",
        }}
      />
      <AbsoluteFill style={{ background: `rgba(${NAVY_RGB},${0.35 * (1 - lit) + 0.25})` }} />
      {caption || eyebrow ? (
        <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", padding: `0 ${90 * u}px`, textAlign: "center", gap: 28 * u, flexDirection: "column" }}>
          {eyebrow ? (
            <div style={{ fontFamily: FONTS.body, fontWeight: 500, fontSize: 38 * u, letterSpacing: "0.22em", textTransform: "uppercase", color: WHITE, ...rise(0.8) }}>{eyebrow}</div>
          ) : null}
          <div style={{ width: rule * 120 * u, height: 3 * u, background: CYAN }} />
          {caption ? (
            <div style={{ fontFamily: FONTS.display, fontVariantNumeric: "lining-nums", fontWeight: 500, fontSize: 104 * u, lineHeight: 1.05, color: WHITE, ...rise(1.0) }}>{caption}</div>
          ) : null}
        </AbsoluteFill>
      ) : null}
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default LuzAcender;
